<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import ActionConfirmationDialog from './ActionConfirmationDialog.vue'
import { useActionConfirmation } from '../composables/useActionConfirmation'

type IssueState = -1 | 0 | 1 | 2
type EditMode = 'add' | 'edit' | 'copy' | null
interface MachineRow { inspMachineNo: string; inspMachineName: string | null; inspMachineType: string | null; inspType: number; baudRate: number | null; parityBit: string | null; dataBit: number | null; stopBit: number | null; endCode: string | null; format1: string | null; format2: string | null; chNo: string | null; inspDriverNo: string | null; description: string | null; creator: string | null; createDate: string | null; issueState: IssueState; dataStamp: number | null; reviser: string | null; reviseDate: string | null }
interface Driver { inspDriverNo: string; functionName?: string | null; description?: string | null }
interface Envelope<T> { items?: T[]; rows?: T[]; data?: T[] }
interface FormValue { inspMachineNo: string; inspMachineName: string; useType: boolean; inspMachineType: string; inspType: number; baudRate: string; parityBit: string; dataBit: string; stopBit: string; endCode: string; format1: string; format2: string; chNo: string; inspDriverNo: string; description: string }

const props = withDefaults(defineProps<{ apiBaseUrl: string; currentUserNo?: string; developmentPreview?: boolean }>(), { currentUserNo: '', developmentPreview: false })
const emit = defineEmits<{ close: [] }>()
const { confirmationMessage, requestConfirmation, resolveConfirmation } = useActionConfirmation()
const mock = computed(() => import.meta.env.DEV && props.developmentPreview)
const storageKey = 'ymes-dev-mock:qc-inspection-machine:v1'
const statusOptions: { value: IssueState; label: string }[] = [{ value: 0, label: '未簽核' }, { value: 1, label: '簽核中' }, { value: 2, label: '已簽核' }, { value: -1, label: '不使用' }]
const baudRates = ['600', '1200', '2400', '4800', '9600', '19200'], parities = ['None', 'Odd', 'Even', 'Mark'], bits = ['7', '8'], stops = ['1', '2'], endCodes = ['0', '3', '10', '13']
const seed: MachineRow[] = [
  { inspMachineNo: 'DEV-INS-001', inspMachineName: 'DEV 電子秤 A', inspMachineType: null, inspType: 0, baudRate: 9600, parityBit: 'None', dataBit: 8, stopBit: 1, endCode: '13', format1: 'WT,####.##', format2: 'NA', chNo: 'NA', inspDriverNo: null, description: 'DEV 自訂 RS232。', creator: 'DEV001', createDate: '2026-11-10T08:00:00+08:00', issueState: 0, dataStamp: 0, reviser: null, reviseDate: null },
  { inspMachineNo: 'DEV-INS-002', inspMachineName: 'DEV 電子秤 B', inspMachineType: 'DEV-RS232-01', inspType: 0, baudRate: 9600, parityBit: 'None', dataBit: 8, stopBit: 1, endCode: '13', format1: 'WT,####.##', format2: 'NA', chNo: 'NA', inspDriverNo: null, description: 'DEV 套用類別。', creator: 'DEV002', createDate: '2026-11-10T09:00:00+08:00', issueState: 1, dataStamp: 1, reviser: 'DEV001', reviseDate: '2026-11-10T10:00:00+08:00' },
  { inspMachineNo: 'DEV-INS-003', inspMachineName: 'DEV 尺寸儀', inspMachineType: 'DEV-USER-01', inspType: 1, baudRate: null, parityBit: null, dataBit: null, stopBit: null, endCode: null, format1: null, format2: null, chNo: null, inspDriverNo: 'DEV-DRIVER-01', description: 'DEV UserDefine 類別。', creator: 'DEV002', createDate: '2026-11-11T08:00:00+08:00', issueState: 2, dataStamp: 2, reviser: 'DEV001', reviseDate: '2026-11-11T10:00:00+08:00' },
  { inspMachineNo: 'DEV-INS-004', inspMachineName: 'DEV 停用樣本', inspMachineType: null, inspType: 1, baudRate: null, parityBit: null, dataBit: null, stopBit: null, endCode: null, format1: null, format2: null, chNo: null, inspDriverNo: 'DEV-DRIVER-02', description: 'DEV 不使用樣本。', creator: 'DEV001', createDate: '2026-11-12T08:00:00+08:00', issueState: -1, dataStamp: 3, reviser: 'DEV001', reviseDate: '2026-11-12T09:00:00+08:00' },
]
const typeSeed: MachineRow[] = [
  { ...seed[1], inspMachineNo: '', inspMachineName: 'DEV RS232 電子秤類別', issueState: 0 },
  { ...seed[2], inspMachineNo: '', inspMachineName: 'DEV UserDefine 尺寸類別', issueState: 0 },
]
const demoDrivers: Driver[] = [{ inspDriverNo: 'DEV-DRIVER-01', functionName: 'ParseDimension', description: 'DEV 尺寸解析' }, { inspDriverNo: 'DEV-DRIVER-02', functionName: 'ParseWeight', description: 'DEV 重量解析' }]
const rows = ref<MachineRow[]>([]), types = ref<MachineRow[]>([]), drivers = ref<Driver[]>([])
const issueState = ref<IssueState>(0), queryText = ref(''), appliedQuery = ref(''), selected = ref<string[]>([]), activeNo = ref('')
const loading = ref(false), busy = ref(false), error = ref(''), notice = ref(''), mode = ref<EditMode>(null), source = ref<MachineRow | null>(null), formError = ref('')
const form = ref<FormValue>(blankForm()), lookup = ref<'type' | 'driver' | null>(null), lookupQuery = ref('')
const userNo = computed(() => props.currentUserNo?.trim() || (mock.value ? 'DEV001' : ''))
const visibleRows = computed(() => rows.value.filter(r => r.issueState === issueState.value && r.inspMachineNo.toLowerCase().includes(appliedQuery.value.toLowerCase())))
const picked = computed(() => visibleRows.value.filter(r => selected.value.includes(r.inspMachineNo)))
const active = computed(() => visibleRows.value.find(r => r.inspMachineNo === activeNo.value) ?? null)
const typeOptions = computed(() => types.value.filter(r => ((r.inspMachineType ?? '') + ' ' + (r.inspMachineName ?? '')).toLowerCase().includes(lookupQuery.value.toLowerCase())))
const driverOptions = computed(() => drivers.value.filter(r => (r.inspDriverNo + ' ' + (r.functionName ?? '') + ' ' + (r.description ?? '')).toLowerCase().includes(lookupQuery.value.toLowerCase())))
const formLocked = computed(() => mode.value === 'edit' && source.value?.issueState === 1)
const title = computed(() => mode.value === 'add' ? '新增' : mode.value === 'copy' ? '複製' : '修改')

function blankForm(): FormValue { return { inspMachineNo: '', inspMachineName: '', useType: false, inspMachineType: '', inspType: 0, baudRate: '', parityBit: '', dataBit: '', stopBit: '', endCode: '', format1: '', format2: '', chNo: '', inspDriverNo: '', description: '' } }
function normalize(v: Record<string, unknown>): MachineRow {
  const g = (k: string): unknown => v[k] ?? v[k[0].toUpperCase() + k.slice(1)]
  return { inspMachineNo: String(g('inspMachineNo') ?? ''), inspMachineName: ((g('inspMachineName') ?? g('inspMachineTypeName')) as string | null) ?? null, inspMachineType: (g('inspMachineType') as string | null) ?? null, inspType: Number(g('inspType') ?? 0), baudRate: g('baudRate') == null ? null : Number(g('baudRate')), parityBit: (g('parityBit') as string | null) ?? null, dataBit: g('dataBit') == null ? null : Number(g('dataBit')), stopBit: g('stopBit') == null ? null : Number(g('stopBit')), endCode: (g('endCode') as string | null) ?? null, format1: (g('format1') as string | null) ?? null, format2: (g('format2') as string | null) ?? null, chNo: (g('chNo') as string | null) ?? null, inspDriverNo: (g('inspDriverNo') as string | null) ?? null, description: (g('description') as string | null) ?? null, creator: (g('creator') as string | null) ?? null, createDate: (g('createDate') as string | null) ?? null, issueState: Number(g('issueState') ?? 0) as IssueState, dataStamp: g('dataStamp') == null ? null : Number(g('dataStamp')), reviser: (g('reviser') as string | null) ?? null, reviseDate: (g('reviseDate') as string | null) ?? null }
}
function list<T>(r: T[] | Envelope<T>): T[] { return Array.isArray(r) ? r : r.items ?? r.rows ?? r.data ?? [] }
function endpoint(path: string): string { if (!props.apiBaseUrl.trim()) throw new Error('目前尚未設定 API 位址。'); return new URL(path.replace(/^\/+/, ''), new URL(props.apiBaseUrl.replace(/\/+$/, '') + '/', window.location.origin)).toString() }
async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const r = await fetch(endpoint(path), { credentials: 'include', ...init })
  if (r.status === 401) { window.location.assign(import.meta.env.BASE_URL + 'login'); throw new Error('登入已逾期，請重新登入。') }
  const b = await r.text()
  if (!r.ok) {
    let message = b
    try {
      const problem: unknown = JSON.parse(b)
      if (problem && typeof problem === 'object') {
        const fields = problem as Record<string, unknown>
        if (typeof fields.detail === 'string' && fields.detail.trim()) message = fields.detail.trim()
        else if (typeof fields.title === 'string' && fields.title.trim()) message = fields.title.trim()
      }
    } catch { /* Keep plain-text errors when the API response is not JSON. */ }
    throw new Error(message || `API 請求失敗 (${r.status})`)
  }
  return (b ? JSON.parse(b) : undefined) as T
}
function persist(): void { localStorage.setItem(storageKey, JSON.stringify(rows.value)) }
function demoRows(): MachineRow[] { try { const v = localStorage.getItem(storageKey); if (v) return (JSON.parse(v) as Record<string, unknown>[]).map(normalize) } catch { /* reset bad preview data */ }; return seed.map(r => ({ ...r })) }
async function load(): Promise<void> {
  loading.value = true; error.value = ''; notice.value = ''
  try { if (mock.value) rows.value = demoRows(); else { const q = new URLSearchParams({ issueState: String(issueState.value) }); if (queryText.value.trim()) q.set('inspMachineNo', queryText.value.trim()); rows.value = list(await api<Record<string, unknown>[] | Envelope<Record<string, unknown>>>('/api/qc/inspection-machines?' + q)).map(normalize) }
    appliedQuery.value = queryText.value.trim(); selected.value = []; activeNo.value = ''; if (!visibleRows.value.length) notice.value = '沒有符合查詢條件的檢測儀器。'
  } catch (e) { error.value = e instanceof Error ? e.message : '載入檢測儀器失敗。' } finally { loading.value = false }
}
async function loadLookups(): Promise<void> { if (mock.value) { types.value = typeSeed.map(r => ({ ...r })); drivers.value = demoDrivers.map(r => ({ ...r })); return }; const [t, d] = await Promise.all([api<Record<string, unknown>[] | Envelope<Record<string, unknown>>>('/api/qc/inspection-machine-parameter-types'), api<Driver[] | Envelope<Driver>>('/api/qc/inspection-drivers')]); types.value = list(t).map(normalize); drivers.value = list(d) }
function open(modeValue: Exclude<EditMode, null>): void {
  if (modeValue !== 'add' && !active.value) { notice.value = '請先選取一筆資料。'; return }
  source.value = modeValue === 'add' ? null : active.value; const r = source.value
  form.value = r ? { inspMachineNo: modeValue === 'copy' ? '' : r.inspMachineNo, inspMachineName: r.inspMachineName ?? '', useType: Boolean(r.inspMachineType), inspMachineType: r.inspMachineType ?? '', inspType: r.inspType, baudRate: r.baudRate == null ? '' : String(r.baudRate), parityBit: r.parityBit ?? '', dataBit: r.dataBit == null ? '' : String(r.dataBit), stopBit: r.stopBit == null ? '' : String(r.stopBit), endCode: r.endCode ?? '', format1: r.format1 ?? '', format2: r.format2 === 'NA' ? '' : r.format2 ?? '', chNo: r.chNo === 'NA' ? '' : r.chNo ?? '', inspDriverNo: r.inspDriverNo ?? '', description: r.description ?? '' } : blankForm()
  mode.value = modeValue; formError.value = ''; lookupQuery.value = ''; void loadLookups().catch(e => { formError.value = e instanceof Error ? e.message : '載入類別/Driver 失敗。' })
}
function chooseType(r: MachineRow): void { form.value.useType = true; form.value.inspMachineType = r.inspMachineType ?? ''; form.value.inspType = r.inspType; form.value.baudRate = r.baudRate == null ? '' : String(r.baudRate); form.value.parityBit = r.parityBit ?? ''; form.value.dataBit = r.dataBit == null ? '' : String(r.dataBit); form.value.stopBit = r.stopBit == null ? '' : String(r.stopBit); form.value.endCode = r.endCode ?? ''; form.value.format1 = r.format1 ?? ''; form.value.format2 = r.format2 === 'NA' ? '' : r.format2 ?? ''; form.value.chNo = r.chNo === 'NA' ? '' : r.chNo ?? ''; form.value.inspDriverNo = r.inspDriverNo ?? ''; lookup.value = null }
function validate(): string { if (!form.value.inspMachineNo.trim()) return '請輸入 InspMachineNo。'; if (form.value.inspMachineNo.length > 50) return 'InspMachineNo 最長 50 個字元。'; if (form.value.inspMachineName.length > 50) return 'InspMachineName 最長 50 個字元。'; if (form.value.useType && !form.value.inspMachineType) return '請選擇 InspMachineType。'; if (form.value.inspType === 0) { const missing = [['baudRate','BaudRate'],['parityBit','ParityBit'],['dataBit','DataBit'],['stopBit','StopBit'],['endCode','EndCode'],['format1','Format1']].find(([k]) => !String(form.value[k as keyof FormValue]).trim()); if (missing) return `RS232 必須提供 ${missing[1]}。` } else if (!form.value.inspDriverNo.trim()) return 'UserDefine 必須選擇 InspDriverNo。'; if (form.value.description.length > 255) return 'Description 最長 255 個字元。'; return '' }
function body(): Record<string, unknown> { const serial = form.value.inspType === 0; return { inspMachineNo: form.value.inspMachineNo.trim().toUpperCase(), inspMachineName: form.value.inspMachineName.trim() || null, inspMachineType: form.value.useType ? form.value.inspMachineType : null, inspType: form.value.inspType, baudRate: serial ? Number(form.value.baudRate) : null, parityBit: serial ? form.value.parityBit : null, dataBit: serial ? Number(form.value.dataBit) : null, stopBit: serial ? Number(form.value.stopBit) : null, endCode: serial ? form.value.endCode : null, format1: serial ? form.value.format1.trim().toUpperCase() : null, format2: serial ? form.value.format2.trim().toUpperCase() || 'NA' : null, chNo: serial ? form.value.chNo.trim() || 'NA' : null, inspDriverNo: serial ? null : form.value.inspDriverNo.trim(), description: form.value.description.trim() || null } }
async function save(keepOpen = false): Promise<void> {
  const v = validate(); if (v) { formError.value = v; return }; if (formLocked.value) { formError.value = '簽核中資料不可修改。'; return }
  if (mode.value === 'edit' && source.value?.inspMachineType && (!form.value.useType || !form.value.inspMachineType)) { formError.value = '舊服務不支援清除既有類別關聯；請保留或改選其他類別。'; return }
  busy.value = true; formError.value = ''; const data = body(), now = new Date().toISOString(), no = String(data.inspMachineNo)
  try { let saved: MachineRow
    if (mock.value) { if (mode.value !== 'edit' && rows.value.some(r => r.inspMachineNo.toUpperCase() === no.toUpperCase())) throw new Error('InspMachineNo 已存在。'); saved = normalize({ ...data, creator: mode.value === 'edit' ? source.value?.creator : userNo.value || 'DEV001', createDate: mode.value === 'edit' ? source.value?.createDate : now, issueState: mode.value === 'edit' ? source.value?.issueState : 0, dataStamp: mode.value === 'edit' ? (source.value?.dataStamp ?? 0) + 1 : 0, reviser: mode.value === 'edit' ? userNo.value || 'DEV001' : null, reviseDate: mode.value === 'edit' ? now : null }); rows.value = mode.value === 'edit' ? rows.value.map(r => r.inspMachineNo === source.value?.inspMachineNo ? saved : r) : [...rows.value, saved]; persist() }
    else if (mode.value === 'edit' && source.value) { saved = normalize(await api<Record<string, unknown>>('/api/qc/inspection-machines/' + encodeURIComponent(source.value.inspMachineNo), { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...data, issueState: source.value.issueState, dataStamp: source.value.dataStamp }) })) }
    else { saved = normalize(await api<Record<string, unknown>>('/api/qc/inspection-machines', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) })) }
    if (!keepOpen) mode.value = null; else { source.value = saved; form.value.inspMachineNo = saved.inspMachineNo; mode.value = 'edit' }; await load(); activeNo.value = saved.inspMachineNo; notice.value = keepOpen ? '資料已套用。' : '資料已儲存。'
  } catch (e) { formError.value = e instanceof Error ? e.message : '儲存檢測儀器失敗。' } finally { busy.value = false }
}
async function remove(): Promise<void> { const chosen = picked.value.length ? picked.value : active.value ? [active.value] : [], eligible = chosen.filter(r => [0,2,-1].includes(r.issueState)); if (!eligible.length) { notice.value = '請選取未簽核、已簽核或不使用資料。'; return }; if (!(await requestConfirmation(`確定刪除 ${eligible.length} 筆檢測儀器？`))) return; busy.value = true; try { for (const r of eligible) { if (mock.value) rows.value = rows.value.filter(x => x.inspMachineNo !== r.inspMachineNo); else await api('/api/qc/inspection-machines/' + encodeURIComponent(r.inspMachineNo) + '?issueState=' + r.issueState + '&dataStamp=' + (r.dataStamp ?? ''), { method: 'DELETE' }) }; if (mock.value) persist(); await load(); notice.value = `已刪除 ${eligible.length} 筆。` } catch (e) { const m = e instanceof Error ? e.message : '刪除失敗。'; await load(); error.value = m } finally { busy.value = false } }
async function approve(): Promise<void> { const chosen = picked.value.length ? picked.value : active.value ? [active.value] : [], eligible = chosen.filter(r => r.issueState === 0); if (!eligible.length) { notice.value = '核准只允許未簽核資料。'; return }; if (!(await requestConfirmation(`確定送出 ${eligible.length} 筆核准？`))) return; busy.value = true; try { for (const r of eligible) { if (mock.value) rows.value = rows.value.map(x => x.inspMachineNo === r.inspMachineNo ? { ...x, issueState: 1, dataStamp: (x.dataStamp ?? 0) + 1, reviser: userNo.value || 'DEV001', reviseDate: new Date().toISOString() } : x); else await api('/api/qc/inspection-machines/' + encodeURIComponent(r.inspMachineNo) + '/approve', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ issueState: r.issueState, dataStamp: r.dataStamp, creator: userNo.value }) }) }; if (mock.value) persist(); await load(); notice.value = `已送出 ${eligible.length} 筆核准。` } catch (e) { const m = e instanceof Error ? e.message : '核准失敗。'; await load(); error.value = m } finally { busy.value = false } }
function showLookup(kind: 'type' | 'driver'): void { lookup.value = kind; lookupQuery.value = '' }
function date(v: string | null): string { return v ? new Date(v).toLocaleString('zh-TW', { hour12: false }) : '' }
function label(v: number): string { return v === 0 ? 'RS232' : 'UserDefine' }
onMounted(() => { void load() })
</script>

<template>
  <main class="machine-page"><header class="heading"><h1>檢測儀器基本資料</h1><span v-if="mock" class="dev">DEV 假資料</span></header><p v-if="error" class="message error">{{ error }}</p><p v-else-if="notice" class="message notice">{{ notice }}</p>
    <section class="query"><fieldset class="states"><legend>狀態</legend><label v-for="s in statusOptions" :key="s.value"><input type="radio" name="insp-state" :checked="issueState === s.value" @change="issueState=s.value; load()">{{ s.label }}</label></fieldset><label>InspMachineNo<input v-model="queryText" maxlength="50" @keydown.enter="load"></label><span>%</span><button class="button" @click="load">查詢</button></section>
    <section class="list"><div class="grid"><table><thead><tr><th><input type="checkbox" aria-label="全選" :checked="visibleRows.length>0 && picked.length===visibleRows.length" @change="selected=($event.target as HTMLInputElement).checked?visibleRows.map(r=>r.inspMachineNo):[]"></th><th>InspMachineNo</th><th>InspMachineName</th><th>InspType</th><th>BaudRate</th><th>DataBit</th><th>StopBit</th><th>Description</th><th>Creator</th><th>CreateDate</th><th>Reviser</th><th>ReviseDate</th></tr></thead><tbody><tr v-for="r in visibleRows" :key="r.inspMachineNo" :class="{active:r.inspMachineNo===activeNo}" @click="activeNo=r.inspMachineNo" @dblclick="open('edit')"><td><input type="checkbox" :checked="selected.includes(r.inspMachineNo)" @click.stop @change="activeNo=r.inspMachineNo; selected=($event.target as HTMLInputElement).checked?[...new Set([...selected,r.inspMachineNo])]:selected.filter(k=>k!==r.inspMachineNo)"></td><td>{{ r.inspMachineNo }}</td><td>{{ r.inspMachineName }}</td><td>{{ label(r.inspType) }}</td><td>{{ r.baudRate ?? '' }}</td><td>{{ r.dataBit ?? '' }}</td><td>{{ r.stopBit ?? '' }}</td><td>{{ r.description }}</td><td>{{ r.creator }}</td><td>{{ date(r.createDate) }}</td><td>{{ r.reviser }}</td><td>{{ date(r.reviseDate) }}</td></tr><tr v-if="!visibleRows.length"><td colspan="12" class="empty">{{ loading?'載入中…':'沒有資料' }}</td></tr></tbody></table></div><aside><button class="button" @click="open('add')">新增(A)</button><button class="button" :disabled="!active" @click="open('edit')">修改(E)</button><button class="button" :disabled="!active" @click="open('copy')">複製(C)</button><button class="button" :disabled="!active && !picked.length" @click="approve">核准</button><button class="button" :disabled="!active && !picked.length" @click="remove">刪除(D)</button><button class="button close" @click="emit('close')">關閉</button></aside></section><footer class="count">資料總筆數 {{ visibleRows.length }}　已選取 {{ picked.length }}</footer>
    <div v-if="mode" class="shade" @click.self="mode=null"><section class="dialog"><header><b>檢測儀器基本資料（{{ title }}）</b><button @click="mode=null">×</button></header><form @submit.prevent="save()"><fieldset class="fields" :disabled="formLocked"><legend>檢測儀器資料</legend>
      <label><span>InspMachineNo</span><input v-model="form.inspMachineNo" maxlength="50" :readonly="mode==='edit'" required></label><label><span>InspMachineName</span><input v-model="form.inspMachineName" maxlength="50"></label>
      <div class="association"><label><input v-model="form.useType" type="checkbox" :disabled="mode==='edit' && !!source?.inspMachineType" @change="!form.useType && (form.inspMachineType='')">套用檢測儀器類別</label><input v-model="form.inspMachineType" readonly placeholder="未套用類別"><button type="button" class="button" :disabled="!form.useType" @click="showLookup('type')">...</button></div>
      <label><span>InspType</span><select v-model.number="form.inspType" :disabled="form.useType || mode==='edit'"><option :value="0">0 — RS232</option><option :value="1">1 — UserDefine</option></select></label>
      <div class="parameters"><header><b>{{ form.useType?'類別帶入':form.inspType===0?'RS232':'UserDefine' }}</b><span>{{ form.useType?'參數取自所選類別':'通訊參數' }}</span></header><div v-if="form.inspType===0" class="serial"><label>BaudRate<select v-model="form.baudRate" :disabled="form.useType"><option value="">請選擇</option><option v-for="x in baudRates" :key="x">{{x}}</option></select></label><label>EndCode<select v-model="form.endCode" :disabled="form.useType"><option value="">請選擇</option><option v-for="x in endCodes" :key="x">{{x}}</option></select></label><label>ParityBit<select v-model="form.parityBit" :disabled="form.useType"><option value="">請選擇</option><option v-for="x in parities" :key="x">{{x}}</option></select></label><label>Format1<input v-model="form.format1" maxlength="50" :readonly="form.useType"></label><label>DataBit<select v-model="form.dataBit" :disabled="form.useType"><option value="">請選擇</option><option v-for="x in bits" :key="x">{{x}}</option></select></label><label>Format2<input v-model="form.format2" maxlength="2" :readonly="form.useType"></label><label>StopBit<select v-model="form.stopBit" :disabled="form.useType"><option value="">請選擇</option><option v-for="x in stops" :key="x">{{x}}</option></select></label><label>ChNo<input v-model="form.chNo" maxlength="10" :readonly="form.useType"></label></div><div v-else class="driver"><span>InspDriverNo</span><input v-model="form.inspDriverNo" readonly><button class="button" type="button" :disabled="form.useType" @click="showLookup('driver')">...</button></div><small v-if="form.inspType===0">EndCode：0 NUL、3 ETX、10 LF、13 CR</small></div>
      <label class="description"><span>Description</span><textarea v-model="form.description" maxlength="255" rows="3"></textarea></label></fieldset><fieldset class="audit"><legend>建立／修改資訊</legend><label>建立人<input :value="mode==='edit'?source?.creator??'':userNo" readonly></label><label>建立日期<input :value="mode==='edit'?date(source?.createDate??null):'儲存時建立'" readonly></label><label>修改人<input :value="mode==='edit'?userNo:''" readonly></label><label>修改日期<input :value="mode==='edit'?'儲存時更新':''" readonly></label></fieldset><p v-if="formError" class="message error">{{ formError }}</p><footer class="actions"><button class="button primary" type="submit" :disabled="busy||formLocked">確定</button><button class="button" type="button" @click="mode=null">關閉</button><button class="button" type="button" :disabled="busy||formLocked" @click="save(true)">套用</button></footer></form></section></div>
    <div v-if="lookup" class="shade" @click.self="lookup=null"><section class="dialog lookup"><header><b>{{ lookup==='type'?'選取檢測儀器類別':'選取檢測 Driver' }}</b><button @click="lookup=null">×</button></header><label class="lookup-query">搜尋<input v-model="lookupQuery"></label><div class="lookup-grid"><table v-if="lookup==='type'"><thead><tr><th>InspMachineType</th><th>InspMachineTypeName</th><th>InspType</th><th></th></tr></thead><tbody><tr v-for="r in typeOptions" :key="r.inspMachineType ?? r.inspMachineName ?? r.inspMachineNo"><td>{{r.inspMachineType}}</td><td>{{r.inspMachineName}}</td><td>{{label(r.inspType)}}</td><td><button class="button" @click="chooseType(r)">選取</button></td></tr></tbody></table><table v-else><thead><tr><th>InspDriverNo</th><th>FunctionName</th><th>Description</th><th></th></tr></thead><tbody><tr v-for="r in driverOptions" :key="r.inspDriverNo"><td>{{r.inspDriverNo}}</td><td>{{r.functionName}}</td><td>{{r.description}}</td><td><button class="button" @click="form.inspDriverNo=r.inspDriverNo;lookup=null">選取</button></td></tr></tbody></table></div></section></div>
  </main>
  <ActionConfirmationDialog :message="confirmationMessage" @resolve="resolveConfirmation" />
</template>

